#include <vector>

class RangeSum {
	std::vector<long long> prefix_sums;
public:
	RangeSum(const std::vector<int>& data) {
		prefix_sums.resize(data.size() + 1, 0);
		for (size_t i = 0; i < data.size(); ++i) {
			prefix_sums[i + 1] = prefix_sums[i] + data[i];
		}
	}
	long long query(int left, int right) {
		return prefix_sums[right + 1] - prefix_sums[left];
	}
};

void process_queries(const std::vector<int>& data, const std::vector<std::pair<int, int>>& queries) {
	RangeSum rs(data);
	for (auto& q : queries) {
		rs.query(q.first, q.second);
	}
}
---
The original code performs an O(N) sum for each of the M queries, resulting in O(N*M) total time. By precomputing a prefix sum array in O(N), each query is reduced to a simple subtraction, achieving O(1) query time and O(N+M) overall complexity.

