class RangeCounter {
	std::vector<int> freq_prefix;
public:
	RangeCounter(const std::vector<int>& vals, int max_possible) {
		freq_prefix.assign(max_possible + 2, 0);
		for (int x : vals) freq_prefix[x + 1]++;
		for (size_t i = 1; i < freq_prefix.size(); ++i)
			freq_prefix[i] += freq_prefix[i - 1];
	}
	int query(int min_v, int max_v) {
		if (min_v > max_v) return 0;
		return freq_prefix[max_v + 1] - freq_prefix[min_v];
	}
};
---
