void apply_updates_fast(std::vector<int>& arr, const std::vector<std::pair<std::pair<int, int>, int>>& updates) {
	std::vector<int> diff(arr.size() + 1, 0);
	for (auto& up : updates) {
		diff[up.first.first] += up.second;
		diff[up.first.second + 1] -= up.second;
	}
	int current_diff = 0;
	for (size_t i = 0; i < arr.size(); ++i) {
		current_diff += diff[i];
		arr[i] += current_diff;
	}
}
