std::vector<int> batch_query_optimized(const std::vector<std::vector<int>>& mat, const std::vector<Rect>& queries) {
	int h = mat.size(), w = mat[0].size();
	std::vector<std::vector<int>> p(h + 1, std::vector<int>(w + 1, 0));
	for (int i = 1; i <= h; ++i)
		for (int j = 1; j <= w; ++j)
