class MatrixAreaProvider {
	std::vector<std::vector<int>> p;
public:
	MatrixAreaProvider(const std::vector<std::vector<int>>& mat) {
		int R = mat.size(), C = mat[0].size();
		p.assign(R + 1, std::vector<int>(C + 1, 0));
		for (int i = 1; i <= R; ++i)
			for (int j = 1; j <= C; ++j)
				p[i][j] = mat[i-1][j-1] + p[i-1][j] + p[i][j-1] - p[i-1][j-1];
	}
	int query(int r1, int c1, int r2, int c2) {
		return p[r2+1][c2+1] - p[r1][c2+1] - p[r2+1][c1] + p[r1][c1];
	}
};
---
The original nested loops for area summation have O(R * C) query complexity. Precomputing a 2D prefix sum table enables O(1) area retrieval, significantly improving efficiency for grid-based calculations.

