class RangeValueFreq {
	std::unordered_map<int, std::vector<int>> p;
public:
	RangeValueFreq(const std::vector<int>& nums) {
		for (size_t i = 0; i < nums.size(); ++i) {
			if (p.find(nums[i]) == p.end()) p[nums[i]].resize(nums.size() + 1, 0);
			p[nums[i]][i+1]++;
		}
		for (auto& entry : p) {
			for (size_t i = 1; i < entry.second.size(); ++i) entry.second[i] += entry.second[i-1];
		}
	}
	int query(int s, int e, int val) {
		if (p.find(val) == p.end()) return 0;
		return p[val][e+1] - p[val][s];
	}
};
---
Linear range scanning takes O(N) per frequency request. Using prefix count arrays per unique value allows O(1) frequency lookups, which is optimal for data analysis on static datasets.

